from pathlib import Path
p=Path('.')
# Add simulation navigation links to every app page sidebar
for f in p.glob('*.html'):
    s=f.read_text()
    marker='<a class="nav-link" href="laws.html">'
    if marker in s and 'circuit-builder.html' not in s:
        insert='''<a class="nav-link" href="circuit-builder.html"><b>⚡</b><span>محاكي الدوائر</span></a>
<a class="nav-link" href="conductors.html"><b>◈</b><span>الموصلات والعوازل</span></a>
<a class="nav-link" href="current-flow.html"><b>〰</b><span>تدفق التيار</span></a>
<a class="nav-link" href="meters.html"><b>▣</b><span>أجهزة القياس</span></a>
'''
        s=s.replace(marker,insert+marker)
    f.write_text(s)
# Add home feature cards
f=p/'home.html'; s=f.read_text(); needle='''          <article class="feature-card" onclick="window.location.href='laws.html'">'''
new='''          <article class="feature-card" onclick="window.location.href='circuit-builder.html'"><div class="feature-icon cyan">⚡</div><h3>محاكي بناء الدوائر</h3><p>اسحب المكونات ووصلها وشاهد الدائرة تعمل.</p><span class="card-arrow">↗</span></article>
          <article class="feature-card" onclick="window.location.href='conductors.html'"><div class="feature-icon green">◈</div><h3>الموصلات والعوازل</h3><p>اختبر المواد واكتشف ما يسمح بمرور التيار.</p><span class="card-arrow">↗</span></article>
          <article class="feature-card" onclick="window.location.href='current-flow.html'"><div class="feature-icon blue">〰</div><h3>محاكاة تدفق التيار</h3><p>غيّر الجهد والمقاومة ولاحظ تغير التيار.</p><span class="card-arrow">↗</span></article>
          <article class="feature-card" onclick="window.location.href='meters.html'"><div class="feature-icon purple">▣</div><h3>مختبر أجهزة القياس</h3><p>تعلّم استخدام الأميتر والفولتميتر والأوميتر.</p><span class="card-arrow">↗</span></article>
'''
s=s.replace(needle,new+needle); f.write_text(s)
# Shared page shell
nav='''<a class="nav-link" href="home.html"><b>⌂</b><span>الرئيسية</span></a><a class="nav-link" href="lab.html"><b>⌁</b><span>المختبر الافتراضي</span></a><a class="nav-link" href="experiments.html"><b>⚗</b><span>التجارب</span></a><a class="nav-link" href="circuit-builder.html"><b>⚡</b><span>محاكي الدوائر</span></a><a class="nav-link" href="conductors.html"><b>◈</b><span>الموصلات والعوازل</span></a><a class="nav-link" href="current-flow.html"><b>〰</b><span>تدفق التيار</span></a><a class="nav-link" href="meters.html"><b>▣</b><span>أجهزة القياس</span></a><a class="nav-link" href="laws.html"><b>∑</b><span>القوانين</span></a><a class="nav-link" href="quiz.html"><b>☷</b><span>الاختبارات</span></a><a class="nav-link" href="profile.html"><b>◉</b><span>الملف الشخصي</span></a>'''
def page(name,title,content,script):
    return f'''<!DOCTYPE html><html lang="ar" dir="rtl" data-page="{name}"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ElectroLab | {title}</title><link rel="stylesheet" href="style.css"><link rel="stylesheet" href="simulations.css"></head><body><div class="app-shell"><aside class="sidebar" id="sidebar"><a class="brand" href="home.html"><span class="brand-mark">ϟ</span><span>Electro<span>Lab</span><small>المختبر الإلكتروني الذكي</small></span></a><nav>{nav}</nav><div class="side-bottom"><div class="online-dot"></div><span>المختبر جاهز للتجربة</span></div></aside><main class="main"><header class="topbar"><button class="mobile-menu" id="mobileMenu">☰</button><div><div class="eyebrow">مساحة التعلم والتجربة</div><div class="page-heading" id="pageHeading">{title}</div></div><div class="top-actions"><button class="lang-btn" id="langToggle">EN</button><div class="avatar" id="avatar">E</div></div></header><section class="page active">{content}</section><footer><span>© eng.ayloool</span><span>مختبر تعليمي تجريبي للإلكترونيات</span></footer></main></div><div class="toast" id="toast"></div><script src="app.js"></script><script src="{script}"></script></body></html>'''
(p/'circuit-builder.html').write_text(page('circuit-builder','محاكي بناء الدوائر', '''<div class="section-title"><div><h2>ابنِ دائرتك بنفسك</h2><p class="muted">أضف المكونات ثم شغّل الدائرة. جرّب دائرة بطارية + مقاومة + LED + أسلاك.</p></div><button class="outline" id="resetCircuit">إعادة ضبط</button></div><div class="sim-layout"><div class="panel"><h3>المكونات</h3><div class="sim-parts"><button data-add="battery">🔋 بطارية</button><button data-add="resistor">〰 مقاومة</button><button data-add="led">🔴 LED</button><button data-add="switch">⏻ مفتاح</button><button data-add="wire">➖ سلك</button></div><p class="muted small">اضغط لإضافة المكوّن إلى لوحة العمل.</p></div><div class="panel"><div class="sim-board-head"><h3>لوحة الدائرة</h3><span class="live-label"><i></i> LIVE SIMULATION</span></div><div class="circuit-canvas" id="circuitCanvas"><div class="circuit-empty" id="circuitEmpty">ابدأ بإضافة المكونات من القائمة</div></div><div class="sim-actions"><button class="primary" id="runSim">▶ تشغيل الدائرة</button><span id="circuitStatus" class="result-text">الدائرة متوقفة</span></div></div></div><div class="panel learning-note"><b>ماذا تتعلم؟</b><p>لا يكفي وجود المكونات فقط؛ يجب أن تتصل في مسار مغلق، مع مقاومة مناسبة لحماية LED.</p></div>''','circuit-sim.js'))
(p/'conductors.html').write_text(page('conductors','مختبر الموصلات والعوازل', '''<div class="section-title"><div><h2>هل تسمح المادة بمرور التيار؟</h2><p class="muted">اختر مادة وضعها في الفجوة الكهربائية، ثم اختبر الدائرة.</p></div></div><div class="sim-layout"><div class="panel"><h3>اختر مادة</h3><div class="material-grid"><button data-material="copper" data-conduct="yes">🟠 النحاس</button><button data-material="aluminum" data-conduct="yes">🥫 الألمنيوم</button><button data-material="iron" data-conduct="yes">🔩 الحديد</button><button data-material="plastic" data-conduct="no">🧩 البلاستيك</button><button data-material="rubber" data-conduct="no">⚫ المطاط</button><button data-material="wood" data-conduct="no">🪵 الخشب الجاف</button><button data-material="glass" data-conduct="no">🔷 الزجاج</button><button data-material="graphite" data-conduct="yes">✏️ الجرافيت</button></div></div><div class="panel"><h3>اختبار الدائرة</h3><div class="conductor-scene"><div class="battery-illustration">🔋</div><div class="test-gap"><span>طرف 1</span><b id="testMaterial">؟</b><span>طرف 2</span></div><div class="bulb" id="testBulb">💡</div></div><button class="primary" id="testMaterialBtn">اختبر المادة</button><div class="result-panel" id="materialResult">اختر مادة أولاً ثم اضغط اختبار.</div></div></div><div class="panel learning-note"><b>قاعدة علمية</b><p>الموصل يسمح بانتقال الشحنات بسهولة نسبية، أما العازل فيقاوم حركة الشحنات. تختلف الموصلية باختلاف نوع المادة ودرجة حرارتها.</p></div>''','conductors-sim.js'))
(p/'current-flow.html').write_text(page('current-flow','محاكاة تدفق التيار', '''<div class="section-title"><div><h2>شاهد تأثير الجهد والمقاومة</h2><p class="muted">حرّك المؤشرات ولاحظ تغير التيار وفق قانون أوم.</p></div></div><div class="panel flow-panel"><div class="flow-controls"><label>الجهد الكهربائي <strong><span id="voltageValue">12</span> V</strong><input id="voltageSlider" type="range" min="1" max="24" value="12"></label><label>المقاومة <strong><span id="resistanceValue">6</span> Ω</strong><input id="resistanceSlider" type="range" min="1" max="24" value="6"></label></div><div class="flow-visual"><div class="pipe-label">مصدر الجهد</div><div class="flow-track"><div class="flow-particles" id="flowParticles"></div><div class="flow-resistor">Ω</div></div><div class="pipe-label">الحمل الكهربائي</div></div><div class="flow-results"><div><small>التيار I</small><strong id="currentValue">2.00 A</strong></div><div><small>القدرة P</small><strong id="powerValue">24.00 W</strong></div><div><small>القانون</small><strong>I = V ÷ R</strong></div></div><p id="flowExplanation" class="result-panel">عند 12 فولت و6 أوم يكون التيار 2 أمبير.</p></div><div class="panel learning-note"><b>جرّب بنفسك</b><p>ثبّت الجهد وزد المقاومة: ماذا يحدث للتيار؟ ثم ثبّت المقاومة وزد الجهد. قارن النتيجتين.</p></div>''','flow-sim.js'))
(p/'meters.html').write_text(page('meters','مختبر أجهزة القياس', '''<div class="section-title"><div><h2>تعلّم القياس داخل الدائرة</h2><p class="muted">اختر جهاز القياس، أدخل قيم الدائرة، ثم اقرأ القياس الافتراضي.</p></div></div><div class="sim-layout"><div class="panel"><h3>جهاز القياس</h3><div class="meter-tabs"><button class="selected" data-meter="voltage">الفولتميتر V</button><button data-meter="current">الأميتر A</button><button data-meter="resistance">الأوميتر Ω</button></div><div class="meter-device"><div class="meter-screen" id="meterScreen">12.0 V</div><div class="meter-knob">◉</div><small id="meterName">Voltmeter · يقيس فرق الجهد</small></div></div><div class="panel"><h3>قيم الدائرة</h3><label class="field-label">الجهد (V)<input id="meterVoltage" type="number" value="12" min="0" step="any"></label><label class="field-label">المقاومة (Ω)<input id="meterResistance" type="number" value="6" min="0.01" step="any"></label><button class="primary" id="readMeter">اقرأ القياس</button><div class="result-panel" id="meterResult">اختر الجهاز واضغط اقرأ القياس.</div></div></div><div class="panel learning-note"><b>تذكّر</b><p>يوصل الفولتميتر على التوازي لقياس فرق الجهد، والأميتر على التوالي لقياس التيار، والأوميتر لقياس المقاومة بعد فصل التغذية عن الدائرة.</p></div>''','meters-sim.js'))
